const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 500, height: 1000 } });
  page.on('console', msg => { if (msg.type() === 'error') console.log('PAGE ERROR:', msg.text()); });
  page.on('pageerror', err => console.log('PAGE EXCEPTION:', err.message));

  await page.goto('http://localhost:8791/index.html', { waitUntil: 'networkidle' });

  // Select Ultra Mode format
  await page.getByRole('button', { name: /Ultra Mode/i }).click();

  // Kick off
  await page.getByRole('button', { name: /Kick Off/i }).click();
  await page.waitForTimeout(1200); // let spin settle

  // Draft: click each candidate then place into an eligible open slot
  for (let i = 0; i < 11; i++) {
    // click candidate card (the spun player, in the "spin" area)
    const cand = page.locator('.fd-spin-card, .fd-candidate, [class*=candidate]').first();
    if (await cand.count() === 0) {
      console.log('No candidate element found, dumping body classes near draft area');
      break;
    }
    await cand.click();
    // click first highlighted/eligible empty slot
    const slot = page.locator('.fd-slot.eligible, .fd-slot.elig, [class*=slot][class*=eligible]').first();
    if (await slot.count() === 0) {
      console.log('No eligible slot found at iteration', i);
      break;
    }
    await slot.click();
    await page.waitForTimeout(150);
    // spin next if not last
    if (i < 10) {
      const spinBtn = page.locator('button:has-text("Spin")').first();
      if (await spinBtn.count()) {
        await spinBtn.click();
        await page.waitForTimeout(700);
      }
    }
  }

  await page.screenshot({ path: '/tmp/pw-test/after_draft.png', fullPage: true });
  console.log('Draft phase screenshot saved.');

  await browser.close();
})();
